#!/usr/bin/env bash
# Standalone source bundle. Creates a new directory; never overwrites an existing one.
set -euo pipefail
bootstrap_source="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/$(basename "${BASH_SOURCE[0]}")"
command -v uv >/dev/null || { echo 'Install uv: https://docs.astral.sh/uv/' >&2; exit 1; }
project_dir="${1:-yt-transcript-mcp}"
if [[ -e "$project_dir" ]]; then
  if [[ "$project_dir" != "." || ! -f pyproject.toml ]]; then
    echo "Refusing to overwrite existing path: $project_dir" >&2; exit 1
  fi
else
  mkdir -p "$project_dir"
  bundle=$(mktemp)
  trap 'rm -f "$bundle"' EXIT
  cat > "$bundle" <<'YT_MCP_BUNDLE'

YT_MCP_BUNDLE
  if [[ "$(uname -s)" == Darwin ]]; then
    base64 -D < "$bundle" | tar -xz -C "$project_dir"
  else
    base64 --decode < "$bundle" | tar -xz -C "$project_dir"
  fi
fi
if [[ "$project_dir" != "." ]]; then cp "$bootstrap_source" "$project_dir/bootstrap_repo.sh"; fi
cd "$project_dir"
uv sync --locked
uv tool install --python 3.13 --constraint requirements.lock --editable .
printf '\nInstalled. Run: yt-mcp doctor\n'
